export type RequestInput={accession_key:string;stable_units:number;fragile_units:number;packing_stations:number;expedited:boolean};
export const score=(stable_units:number,fragile_units:number,packing_stations:number,expedited:boolean)=>{const artifact_total=stable_units+fragile_units,packing_units=stable_units*6+fragile_units*11+(expedited?packing_stations*4:0),overflow_units=Math.max(packing_units-packing_stations*40,0);return packing_units+overflow_units*5+Math.floor(artifact_total/5)*7};
export const calculate=(v:RequestInput)=>{const t=v.stable_units+v.fragile_units,x=v.stable_units*6+v.fragile_units*11+(v.expedited?v.packing_stations*4:0),c=v.packing_stations*40,o=Math.max(x-c,0);return {accession_key:v.accession_key,artifact_total:t,packing_units:x,capacity_units:c,overflow_units:o,inspection_rounds:Math.floor(t/5),priority_score:score(v.stable_units,v.fragile_units,v.packing_stations,v.expedited),accession_state:o===0?'accepted':'queued'}};export async function loadParley(){return {artifact_priority_score:(a0:number,a1:number,a2:number,a3:boolean)=>BigInt(score(a0,a1,a2,a3))}}

